val form = @Composable { modifier: Modifier ->
    Column(
        modifier = modifier.padding(MonarchTheme.spacing.space4),
        verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4),
    ) {
        MonarchText(text = "Persona", style = MonarchTextStyle.Subheading)
        Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
            MonarchAiAgentAvatar(agent = agent, size = MonarchAvatarSize.Lg, decorative = true)
            Column(
                modifier = Modifier.weight(1f),
                verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
            ) {
                MonarchTextField(
                    value = name,
                    onValueChange = { name = it; saved = false },
                    label = "Name",
                    required = true,
                    errorText = if (triedSave && name.isBlank()) "Give the agent a name." else null,
                )
                MonarchTextField(
                    value = role,
                    onValueChange = { role = it; saved = false },
                    label = "Role",
                    helperText = "One line shown under the name, e.g. “Support assistant”.",
                )
            }
        }
        MonarchText(text = "Instructions", style = MonarchTextStyle.Subheading)
        MonarchText(
            text = "How the agent should behave, what to focus on and what to avoid.",
            style = MonarchTextStyle.Caption,
            color = MonarchTheme.colors.textMuted,
        )
        MonarchTextField(
            value = instructions,
            onValueChange = { instructions = it.take(maxInstructions); saved = false },
            label = "Instructions",
            labelVisibility = MonarchTextFieldLabelVisibility.Hidden,
            minLines = 8,
            helperText = "${instructions.length} / ${"%,d".format(Locale.ENGLISH, maxInstructions)} characters",
            singleLine = false,
        )
        MonarchText(text = "Tools", style = MonarchTextStyle.Subheading)
        MonarchText(
            text = "Actions the agent may take. It asks before running anything that changes data.",
            style = MonarchTextStyle.Caption,
            color = MonarchTheme.colors.textMuted,
        )
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .border(1.dp, MonarchTheme.colors.borderSubtle, MonarchTheme.shapes.md)
                .padding(MonarchTheme.spacing.space3),
            verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
        ) {
            toolList.forEach { (id, label, description) ->
                MonarchCheckbox(
                    checked = id in tools,
                    onCheckedChange = { on -> tools = if (on) tools + id else tools - id; saved = false },
                    label = label,
                    description = description,
                )
            }
        }
        MonarchText(text = "Knowledge", style = MonarchTextStyle.Subheading)
        MonarchText(
            text = "Sources the agent can read to ground its answers.",
            style = MonarchTextStyle.Caption,
            color = MonarchTheme.colors.textMuted,
        )
        MonarchAiKnowledgeScope(
            sources = sources,
            selection = knowledge,
            onSelectionChange = { knowledge = it; saved = false },
            expandIcon = {
                MonarchIcon(
                    imageVector = SampleIcons.ChevronRight,
                    contentDescription = null,
                    size = MonarchIconSize.Sm,
                )
            },
        )
        Row(
            horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            MonarchText(
                text = if (saved) "Agent saved." else "",
                modifier = Modifier.weight(1f).semantics { liveRegion = LiveRegionMode.Polite },
            )
            MonarchButton(
                text = "Save agent",
                onClick = {
                    triedSave = true
                    // The app saves definition() on its server here.
                    saved = name.isNotBlank()
                },
                variant = MonarchButtonVariant.Primary,
            )
        }
    }
}
val test = @Composable { modifier: Modifier ->
    Column(
        modifier = modifier.padding(MonarchTheme.spacing.space4),
        verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
    ) {
        Row(
            horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            MonarchAiAgentAvatar(
                agent = agent,
                state = if (status == MonarchAiConversationStatus.Streaming) {
                    MonarchAiAgentState.Working
                } else {
                    MonarchAiAgentState.Idle
                },
                size = MonarchAvatarSize.Sm,
                decorative = true,
            )
            MonarchText(text = "Test", style = MonarchTextStyle.Subheading, modifier = Modifier.weight(1f))
            MonarchButton(
                text = "Restart test",
                onClick = {
                    conversation.stop()
                    conversation.reset()
                },
                variant = MonarchButtonVariant.Ghost,
                size = MonarchButtonSize.Sm,
                enabled = messages.isNotEmpty(),
            )
        }
        MonarchText(text = "Try the agent with the current settings. Nothing here is saved.", style = MonarchTextStyle.Caption)
        @OptIn(ExperimentalMonarchApi::class)
        MonarchAiThread(
            messages = messages,
            modifier = Modifier.weight(1f),
            status = status,
            daySeparators = false,
            onStop = conversation::stop,
            empty = { MonarchText(text = "Send a message to try the agent.") },
        )
        MonarchAiPromptInput(
            label = "Message the agent",
            state = prompt,
            onSubmit = { text -> check(conversation.send(text, body = mapOf("agent" to definition()))) { "Not sent" } },
            busy = status == MonarchAiConversationStatus.Submitted ||
                status == MonarchAiConversationStatus.Streaming,
            onStop = conversation::stop,
        )
    }
}
Column(modifier = Modifier.fillMaxWidth()) {
    form(Modifier)
    Box(
        modifier = Modifier
            .padding(horizontal = MonarchTheme.spacing.space4)
            .fillMaxWidth()
            .border(1.dp, MonarchTheme.colors.borderSubtle, MonarchTheme.shapes.md),
    ) {
        test(Modifier.height(MonarchTheme.spacing.space24 * 3))
    }
}

examples.setupTemplate:
val maxInstructions = 8000
var name by rememberSaveable { mutableStateOf({{agent.name}}) }
var role by rememberSaveable { mutableStateOf({{agent.role}}) }
var instructions by rememberSaveable {
    mutableStateOf({{agent.instructions}})
}
var knowledge by remember { mutableStateOf(listOf({{agent.knowledge.0}})) }
var tools by remember { mutableStateOf(listOf({{agent.tools.0}})) }
val toolList = listOf(
    Triple({{tools.0.id}}, {{tools.0.name}}, {{tools.0.description}}),
    Triple({{tools.1.id}}, {{tools.1.name}}, {{tools.1.description}}),
    Triple({{tools.2.id}}, {{tools.2.name}}, {{tools.2.description}}),
)
var triedSave by remember { mutableStateOf(false) }
var saved by remember { mutableStateOf(false) }
var tab by rememberSaveable { mutableIntStateOf(0) }
val sources = listOf(
    MonarchAiKnowledgeSource(
        id = {{sources.0.id}},
        label = {{sources.0.label}},
        kind = MonarchAiKnowledgeSourceKind.Space,
        children = listOf(
            MonarchAiKnowledgeSource({{sources.0.children.0.id}}, {{sources.0.children.0.label}}, MonarchAiKnowledgeSourceKind.Document),
            MonarchAiKnowledgeSource({{sources.0.children.1.id}}, {{sources.0.children.1.label}}, MonarchAiKnowledgeSourceKind.Document),
        ),
    ),
    MonarchAiKnowledgeSource({{sources.1.id}}, {{sources.1.label}}, MonarchAiKnowledgeSourceKind.App),
)
// The test chat runs the unsaved definition: the transport reads it from the request body.
val transport = remember {
    object : MonarchAiTransport {
        override fun stream(request: MonarchAiTransportRequest): Flow<MonarchAiStreamEvent> = flowOf(
            MonarchAiStreamEvent.TextDelta("The agent received: " + request.messages.lastOrNull()?.text.orEmpty()),
            MonarchAiStreamEvent.Done(),
        )
    }
}
val conversation = rememberMonarchAiConversation(transport)
val messages by conversation.messages.collectAsState()
val status by conversation.status.collectAsState()
val prompt = rememberTextFieldState()
val agent = MonarchAiAgentRef(name = name.ifBlank { "New agent" }, role = role.ifBlank { null })
fun definition() = MonarchAiJSON.Object(
    mapOf(
        "name" to MonarchAiJSON.Text(name),
        "role" to MonarchAiJSON.Text(role),
        "instructions" to MonarchAiJSON.Text(instructions),
        "tools" to MonarchAiJSON.Array(
            tools.map { MonarchAiJSON.Text(it) },
        ),
        "knowledge" to MonarchAiJSON.Array(knowledge.map { MonarchAiJSON.Text(it) }),
    ),
)

