    mutableStateOf("Answer from the team handbook. Keep answers short and link the source.")
}
var knowledge by remember { mutableStateOf(listOf("handbook")) }
var tools by remember { mutableStateOf(listOf("search")) }
val toolList = listOf(
    Triple("search", "Search documents", "Reads documents the agent can see."),
    Triple("tasks", "Create tasks", "Asks before creating anything."),
    Triple("email", "Draft email", "Drafts only; never sends."),
)
